/* cppi::fa346ba6233223b83a229ca61cd4daabc3ad0b9dd215d151cc0cf18dc3ea8a70 */
select distinct request_id, start_date, end_date, pool, strategy_alternative, weight, start_date as business_date
from performance.tpm_tpm_atp_weights where request_id = 
(select max(request_id) from performance.tpm_tpm_atp_weights where start_date = '2025-04-10' and end_date = '2025-04-10')
and start_date = '2025-04-10' and end_date = '2025-04-10'

/* cppi::06b16eaff06741e2ef4f3a6909204aa480e7f0596fe22677b7f6f69c642d4777 */
SELECT * from performance.scd_performance_invstr_flatten
where business_date = '2025-03-31'

/* cppi::0703e8434d42ff28d9317a5f60423704a8fb6585db6d3bec144c7c84f916348e */
-- Athena JDBC driver connection test
SELECT 1

/* cppi::cb02cb6eac43e22f110d6f5b7581d6f8094e6b9e2b3f34df20aa71554e3b0a8c */
/* QuickSight 6d3d7a1c-ba1a-4656-938a-d433cf7bacf5 */
SELECT "business_date", "year", "from_currency", "to_currency", "rate_type_code", "source", "bid_price", "ask_price", "mid_price", "factor", "inverse_quoted", "last_update_date", "vendor_file_name", "arrival_time"
FROM (SELECT *
FROM market.refinitiv_exchange_rates_wmr) AS "FX Rates - EUR, GBP, USD (PROD)"

/* cppi::a7a11545bb3f0847672fdf6dc0990e2c4665489bc12d8b926a98c660c151c003 */
SELECT * FROM "risk_prod"."rmv_credit_exposure"
where business_date = '2025-06-10'

/* cppi::0703e8434d42ff28d9317a5f60423704a8fb6585db6d3bec144c7c84f916348e */
-- Athena JDBC driver connection test
